fill(doc.tables[1],[('GET /api/loans','page, size, status','items,total,page,size','401,422'),('GET /api/loans/{id}','id','Выдача, читатель, книга, штраф','401,404'),('GET /api/summary','—','on_hands,overdue,top_books','401'),('POST /api/loans','reader_id,copy_id,days','201; созданная выдача','401,404,409,422'),('POST /api/loans/{id}/return','id','200; выдача, штраф','401,404,409')])
fill(doc.tables[2],[('Машина','Указать CPU, RAM и ОС фактического стенда'),('Среда выполнения стенда','Docker Compose; версии подтвердить'),('Учётная запись','librarian'),('Число повторов в серии','20 для каждой операции'),('Прогрев','1 запрос, исключён из статистики'),('Чем измерялось время','measure.py, perf_counter; p95 ближайший ранг')])
