    a={x['operation']:x for x in small['summary']};b={x['operation']:x for x in work['summary']}
    fill(doc.tables[4],[(name[k],*(f'{a[k][x]:.3f}' for x in ('p50_ms','p95_ms')),*(f'{b[k][x]:.3f}' for x in ('p50_ms','p95_ms')),f"{b[k]['p50_ms']/a[k]['p50_ms']:.2f}") for k in a])
